impl fmt::Display for Decimal128 {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // A NaN value is formatted directly from its bits (matches the Go
        // decimal128BIDStringPort NaN branch: sign, NaN/SNaN, canonical
        // payload). Every other value routes through the Intel
        // bid128_to_string converter.
        if let Some(s) = format_decimal128_nan(self.0) {
            return f.write_str(&s);
        }
        f.write_str(&crate::generated::bid128_string::bid128_to_string(super::types::bid_uint128_from_le_bytes(self.0)))
    }
}

impl FromStr for Decimal128 {
    type Err = ParseDecimalError;
    fn from_str(s: &str) -> Result<Decimal128, ParseDecimalError> {
        Decimal128::parse(s)
    }
}

